import {callTool,listTools} from './server.mjs';
async function tryRun(fn){try{const r=await fn();console.log('OK',JSON.stringify(r));}catch(e){console.log('ERR',e.message);}}
// unknown tool
await tryRun(()=>callTool('foo',{}));
// missing session
await tryRun(()=>callTool('get_value',{session_id:'nope',key:'k'}));
// extra args
await tryRun(()=>callTool('begin_session',{session_id:'s3',extra:1}));
// empty session_id
await tryRun(()=>callTool('begin_session',{session_id:''}));
// empty key
await tryRun(()=>callTool('put_value',{session_id:'s3',key:'',value:'v'}));
// non-string value
await tryRun(()=>callTool('put_value',{session_id:'s3',key:'k',value:123}));
// isolation
await callTool('begin_session',{session_id:'a'});
await callTool('begin_session',{session_id:'b'});
await callTool('put_value',{session_id:'a',key:'x',value:'secret'});
await tryRun(()=>callTool('get_value',{session_id:'b',key:'x'}));
await tryRun(()=>callTool('get_value',{session_id:'a',key:'x'}));
// tools have additionalProperties:false
console.log(JSON.stringify((await listTools()).map(t=>t.inputSchema.additionalProperties)));
""}

